command:
"=== finding Android Studio uninstaller ==="
$u = "C:\Program Files\Android\Android Studio\uninstall.exe"
if (Test-Path $u) {
  "found, uninstalling silently..."
  Start-Process -FilePath $u -ArgumentList "/S" -Wait
  "done"
} else {
  "uninstaller not found at default path"
  Get-ChildItem "C:\Program Files\Android" -ErrorAction SilentlyContinue | Select-Object Name
}
